package hu.synostream.android;
import android.content.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.json.*;import java.util.*;
@RunWith(AndroidJUnit4.class) public class Android0518Test {
 final Android050FlowTest f=new Android050FlowTest();static final String FILE="/Movies/Demo.Movie.2020.mkv";
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{f.instrumentation.runOnMainSync(()->f.app.automaticForeground(false));f.instrumentation.waitForIdleSync();long deadline=android.os.SystemClock.elapsedRealtime()+20000;while((f.app.busy||f.app.scanRunning)&&android.os.SystemClock.elapsedRealtime()<deadline)Thread.sleep(50);f.instrumentation.waitForIdleSync();f.instrumentation.runOnMainSync(()->{f.app.automaticForeground(false);f.app.cancelScan();f.app.metadataBusy=false;f.app.epoch++;});f.cleanup();}
 void waitFor(java.util.function.BooleanSupplier condition)throws Exception{long end=android.os.SystemClock.elapsedRealtime()+20000;while(!condition.getAsBoolean()&&android.os.SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertTrue("Deletion did not finish",condition.getAsBoolean());}
 void movie(FakeNas nas)throws Exception{Library.Card card=new Library.Card(FILE,"Delete fixture",true);f.setup(nas,List.of(card));nas.files.put("/Movies/Demo.Movie.2020.nfo",new byte[]{1});f.device.findObject(By.desc("Delete fixture")).click();assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/detail_delete")),5000));}
 void open()throws Exception{assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/detail_delete")),5000));f.device.findObject(By.res(f.pkg+":id/detail_delete")).click();assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/confirm_media_delete").enabled(true)),10000));}
 void confirm(){f.device.findObject(By.res(f.pkg+":id/confirm_media_delete")).click();}
 @Test public void cancelDoesNotDeleteAndConfirmationDeletesOnlyChosenMovie()throws Exception{try(FakeNas nas=new FakeNas()){movie(nas);open();assertEquals(0,nas.mediaDeletes);f.text("Mégse");assertTrue(nas.files.containsKey(FILE));open();confirm();waitFor(()->!nas.files.containsKey(FILE)&&!f.app.metadataBusy);assertFalse(nas.files.containsKey("/Movies/Demo.Movie.2020.nfo"));assertTrue(nas.files.containsKey("/Movies/Another.Movie.2021.mkv"));assertTrue(nas.folders.contains("/Movies"));assertTrue(f.app.rawCards.stream().noneMatch(c->c.path.equals(FILE)));}}
 @Test public void chooseOneSeasonRetainsOtherSeasonAndSharedNfo()throws Exception{try(FakeNas nas=new FakeNas()){String root="/Series/First.Show";nas.files.keySet().removeIf(p->p.startsWith(root+"/"));nas.folders.add(root+"/Season 1");nas.folders.add(root+"/Season 2");nas.files.put(root+"/Season 1/S01E01.mkv",new byte[]{1});nas.files.put(root+"/Season 1/release.nfo",new byte[]{1});nas.files.put(root+"/Season 2/S02E01.mkv",new byte[]{1});nas.files.put(root+"/tvshow.nfo",new byte[]{1});f.setup(nas,List.of());MainActivity activity=f.activity();f.instrumentation.runOnMainSync(()->{try{JSONObject library=LibraryConfig.defaultLibrary(f.app.libraries,false);LibraryConfig.paths(library,List.of("/Series"));f.app.selectedLibrary=library.optString("id");f.app.page="shows";Library.Card card=new Library.Card(root,"Series delete fixture",false);card.episodeRoots.add(root);f.app.rawCards=new ArrayList<>(List.of(card));f.app.cards=new ArrayList<>(List.of(card));activity.invalidatePage();}catch(Exception e){throw new RuntimeException(e);}});assertTrue(f.device.wait(Until.hasObject(By.desc("Series delete fixture")),5000));f.device.findObject(By.desc("Series delete fixture")).click();assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/detail_delete")),5000));f.device.findObject(By.res(f.pkg+":id/detail_delete")).click();assertTrue(f.device.wait(Until.hasObject(By.text("1. évad")),10000));f.text("1. évad");confirm();waitFor(()->!f.app.metadataBusy);assertFalse(nas.files.containsKey(root+"/Season 1/S01E01.mkv"));assertFalse(nas.folders.contains(root+"/Season 1"));assertTrue(nas.files.containsKey(root+"/Season 2/S02E01.mkv"));assertTrue(nas.files.containsKey(root+"/tvshow.nfo"));}}
 @Test public void changedFolderAfterReviewRejectsWithoutDelete()throws Exception{try(FakeNas nas=new FakeNas()){movie(nas);open();nas.files.put("/Movies/New.After.Review.mkv",new byte[]{1});confirm();assertTrue(f.device.wait(Until.hasObject(By.textContains("megváltozott")),10000));assertEquals(0,nas.mediaDeletes);assertTrue(nas.files.containsKey(FILE));f.text("Mégse");}}
}
